const FROM = { email: "commande@e-carpet.shop", name: "E-Carpet" };

export function emailConfigured() {
  return Boolean(process.env.BREVO_API_KEY);
}

export async function sendEmail({ to, subject, html }) {
  const key = process.env.BREVO_API_KEY;
  if (!key) throw new Error("BREVO_API_KEY manquante");

  const res = await fetch("https://api.brevo.com/v3/smtp/email", {
    method: "POST",
    headers: { "api-key": key, "content-type": "application/json", accept: "application/json" },
    body: JSON.stringify({ sender: FROM, to: [{ email: to }], subject, htmlContent: html }),
  });
  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new Error(body.message || `échec de l'envoi (${res.status})`);
  }
  return res.json();
}

