// Carte statique Yandex (aucune clé API requise, contrairement à Google/Mapbox) ;
// le clic ouvre l'itinéraire Google Maps vers l'adresse du point relais.
function pickupMap(pickupPoint) {
  if (!pickupPoint?.lat || !pickupPoint?.long) return "";
  const { lat, long } = pickupPoint;
  const mapSrc = `https://static-maps.yandex.ru/1.x/?ll=${long},${lat}&size=450,180&z=16&l=map&pt=${long},${lat},pm2rdm&lang=fr_FR`;
  const gmaps = `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(`${pickupPoint.adresse}, ${pickupPoint.codePostal} ${pickupPoint.ville}`)}`;
  return `
    <a href="${gmaps}" style="display:block;margin-top:10px">
      <img src="${mapSrc}" alt="Localisation du point relais" width="416" style="display:block;width:100%;max-width:416px;height:auto;border-radius:8px;border:1px solid #e4e4e7" />
    </a>
  `;
}

function formatHorairesCourt(horaires) {
  if (!horaires) return "";
  let lignes = [];
  if (Array.isArray(horaires)) lignes = horaires.filter(Boolean).map(String);
  else if (typeof horaires === "object") {
    const jours = { monday: "Lun", tuesday: "Mar", wednesday: "Mer", thursday: "Jeu", friday: "Ven", saturday: "Sam", sunday: "Dim" };
    lignes = Object.entries(horaires)
      .filter(([, v]) => v)
      .map(([j, c]) => `${jours[j.toLowerCase()] || j} : ${Array.isArray(c) ? c.join(", ") : c}`);
  } else if (typeof horaires === "string") lignes = [horaires];
  if (lignes.length === 0) return "";
  return `
    <p style="margin:8px 0 0;font-size:11px;font-weight:700;color:#18181b">Horaires d'ouverture</p>
    <p style="margin:1px 0 0;font-size:12px;line-height:1.5;color:#71717a">${lignes.join("<br/>")}</p>
  `;
}

