function listeFr(noms) {
  if (noms.length <= 1) return noms.join("");
  return `${noms.slice(0, -1).join(", ")} et ${noms[noms.length - 1]}`;
}

export function cartReminderEmail({ items }) {
  const noms = items.map((it) => it.name);
  const verbe = noms.length > 1 ? "sont toujours" : "est toujours";
  return {
    subject: "Vous avez oublié quelque chose · E-Carpet",
    html: lightLayout(`
      <div style="padding:28px 32px 32px">
        <h1 style="font-size:22px;font-weight:800;margin:0 0 16px;color:#18181b">Votre panier vous attend</h1>
        <p style="margin:0 0 20px;font-size:14px;line-height:1.5;color:#3f3f46">
          ${listeFr(noms)} ${verbe} dans votre panier. Il ne reste plus qu'à finaliser votre commande.
        </p>
        <a href="https://e-carpet.shop/panier" style="display:inline-block;background:#e06a3b;color:#fff;padding:12px 24px;border-radius:999px;text-decoration:none;font-weight:700">Reprendre ma commande</a>
      </div>
    `),
  };
}
